import type {
	IndexedDbOfflineStoreAdapter,
	OfflineOperation,
	SyncStats
} from '@dafuga01/offline-sync';
export interface OfflineSyncConfig {
	/** Stable application/account/tenant scope; change it when the authenticated actor changes. */
	scope: string;
	collections: readonly string[];
	/** Observe backend reachability, not just navigator.onLine. */
	isOnline: () => boolean;
	fetch?: typeof globalThis.fetch;
	store?: IndexedDbOfflineStoreAdapter;
	onStats?: (stats: SyncStats) => void;
	onError?: (error: unknown) => void;
}
export interface OfflineMutation {
	collection: string;
	action: string;
	input: unknown;
	baseRevision?: string;
}
export interface OfflineStreamFrame {
	type: 'start' | 'record' | 'delete' | 'checkpoint' | 'complete';
	scope?: string;
	collection?: string;
	id?: string;
	value?: unknown;
	cursor?: string;
}
export type { OfflineOperation };

export interface OfflineLocalRecord {
	id: string;
	value: unknown;
}

